// Code generated by xgen. DO NOT EDIT.
// Source: xgen/screens/src/authoring/blocks/post-showcase.ts
/**
 * Posts shown off. Axes: layout (intro: four small post cards beside the intro with a view-all link, featured:
 * the first post in detail beside its picture, overlay: cards with the text over the picture), cols (2, 3:
 * overlay columns), mediaSide, tone.
 */
import { Fragment, type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Link } from "../primitives/link/link";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { MediaFrame } from "../components/media-frame";
import { PostFeature } from "../components/post-feature";
import { PostMiniCard } from "../components/post-mini-card";
import { PostOverlayCard } from "../components/post-overlay-card";
import { SectionFrame } from "../components/section-frame";
import type { Post, PostLabels } from "./post-card.types";
import type { HeadLink } from "../components/section-frame.types";

export type PostShowcaseProps = {
  id: string;
  title: string;
  lead?: string;
  badge?: string;
  posts: Post[];
  labels: PostLabels;
  action: HeadLink;
  layout?: "intro" | "featured" | "overlay";
  cols?: "2" | "3";
  mediaSide?: "end" | "start";
  tone?: "default" | "muted";
};

export function PostShowcase({
  id,
  title,
  lead = "",
  badge = "",
  posts,
  labels,
  action,
  layout = "intro",
  cols = "3",
  mediaSide = "start",
  tone = "default",
}: PostShowcaseProps) {
  return (
    <>
      {((layout as string) === "intro") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge }}
          tone={tone}
          layout="split"
          media={{ show: true, side: mediaSide }}
          aside={(
            <Box className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              {(posts ?? []).map((p, i) => (
                <Fragment key={p.id}>
                  {(i < 4) ? (
                    <PostMiniCard p={p} labels={labels} />
                  ) : null}
                </Fragment>
              ))}
            </Box>
          )}
        >
          <Link href={action.href} size="sm" data-testid="section-action">
            {action.label}
            <LucideIcon name="arrow-right" size={16} />
          </Link>
        </SectionFrame>
      ) : ((layout as string) === "featured") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge }}
          tone={tone}
          layout="split"
          media={{ show: true, side: mediaSide }}
          aside={(
            <MediaFrame alt={title} ratio="4/3" />
          )}
        >
          {(posts ?? []).map((p, i) => (
            <Fragment key={p.id}>
              {(i < 1) ? (
                <PostFeature p={p} labels={labels} />
              ) : null}
            </Fragment>
          ))}
        </SectionFrame>
      ) : (
        <SectionFrame id={id} title={title} lead={lead} heading={{ badge }} tone={tone}>
          <Box
            className={
              (cols as string) === "2" ? "grid grid-cols-1 gap-6 md:grid-cols-2"
              : "grid grid-cols-1 gap-6 md:grid-cols-3"
            }
          >
            {(posts ?? []).map((p, i) => (
              <Fragment key={p.id}>
                {(i < (((cols as string) === "2") ? 2 : 3)) ? (
                  <PostOverlayCard p={p} labels={labels} ratio={(((cols as string) === "2") ? "16/9" : "4/3")} />
                ) : null}
              </Fragment>
            ))}
          </Box>
        </SectionFrame>
      )}
    </>
  );
}
